.dock .tab:hover {
  background: rgba(255,255,255,0.08);
  color: var(--txt);
  transform: translateY(-1px);
}
.dock .tab.sel {
  background: var(--amber-grad);
  border-color: transparent;
  color: var(--amber-deep);
  font-weight: 650;
  box-shadow: 0 4px 16px rgba(224, 164, 88, 0.35), inset 0 1px 0 rgba(255,255,255,0.3);
}
.dock .tab.sel::before { display: none; }
/* ---- bottom settings panel: two-column grid, fills the width ------------ */
.pages {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 24px 26px;
  background: rgba(0, 0, 0, 0.10);
}
.page { display: none; }
.page.sel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 22px;
  align-content: start;
  animation: page-in 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
.page.sel > .group.wide { grid-column: 1 / -1; }
.page.sel > .page-header { grid-column: 1 / -1; }
@keyframes page-in {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.page-header { margin-bottom: 16px; }
.page-header h1 {
  position: relative;
  display: inline-block;
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--txt);
  margin-bottom: 6px;
}
.page-header h1::after {
  content: "";
  position: absolute;
  left: 0; bottom: -5px;
  width: 36px; height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--amber), transparent);
  opacity: 0.75;
}
.page-header p {
  margin-top: 9px;
  font-size: 12.5px;
  color: var(--sec);
  max-width: 520px;
  line-height: 1.5;
}

/* ---- grouped form cards ---------------------------------------------------- */
.group { margin-bottom: 24px; max-width: 100%; min-width: 0; }
.group.wide { max-width: 100%; }
.ghead {
  font-size: 11px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--txt-secondary);
  margin: 0 2px 9px;
}
.gcard {
  background: var(--glass);
  border: 1px solid var(--hair);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: border-color 0.18s ease, transform 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}
.gcard:hover {
  border-color: rgba(232, 176, 106, 0.18);
  transform: translateY(-1px);
}
.gcard.pad { padding: 13px 16px; }
/* direct caption children must not hug the card edge */
.gcard > .cap { padding: 6px 16px; }
.gcard.pad > .cap { padding: 6px 0; }

/* rows inside a card, separated by hairlines */
.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 30px;
  padding: 11px 16px;
  border-top: 1px solid var(--hair);
  font-size: 13px;
  color: var(--txt-secondary);
}
.row > span:first-child { color: var(--txt); }
.gcard > .row:first-child { border-top: 0; }
.gcard.pad .row { padding: 6px 0; border-top: 0; }
.row.tight { padding-bottom: 2px; }
.row.center { justify-content: center; }
.row .rt { display: flex; flex-direction: column; gap: 3px; }
.cap { font-size: 11.5px; color: var(--sec); line-height: 1.45; }
.dim { color: var(--sec); }
label.row { cursor: pointer; }
.row.link { cursor: pointer; }
.row.link:hover { background: var(--card-hover); }

/* ---- controls -------------------------------------------------------------- */
select {
  background: rgba(255,255,255,0.06); color: var(--txt);
  border: 1px solid var(--hair); border-radius: 9px;
  padding: 5px 10px; font-size: 12.5px; cursor: pointer;
  outline: none;
  transition: border-color 0.15s ease;
}
select:focus { border-color: rgba(232,176,106,0.5); }
select option { background: #1A150E; color: var(--txt); }

/* ember switch (toggle) */
input[type="checkbox"] {
  appearance: none; -webkit-appearance: none;
  width: 40px; height: 24px; border-radius: 12px; flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.14); position: relative;
  transition: background 0.22s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.22s ease;
  cursor: pointer; margin: 0;
}
input[type="checkbox"]::before {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 20px; height: 20px; border-radius: 50%;
  background: #F6F0E4;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
  transition: left 0.22s cubic-bezier(0.22, 1, 0.36, 1), transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
input[type="checkbox"]:checked {
  background: var(--amber-grad);
  box-shadow: 0 0 10px rgba(232, 176, 106, 0.32);
}
input[type="checkbox"]:checked::before { left: 18px; }
input[type="checkbox"]:active::before { transform: scale(0.9); }


