}
select:focus { border-color: rgba(232,176,106,0.5); }
select option { background: #1A150E; color: var(--txt); }

/* ember switch (toggle) */
input[type="checkbox"] {
  appearance: none; -webkit-appearance: none;
  width: 40px; height: 24px; border-radius: 12px; flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.14); position: relative;
  transition: background 0.22s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.22s ease;
  cursor: pointer; margin: 0;
}
input[type="checkbox"]::before {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 20px; height: 20px; border-radius: 50%;
  background: #F6F0E4;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
  transition: left 0.22s cubic-bezier(0.22, 1, 0.36, 1), transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
input[type="checkbox"]:checked {
  background: var(--amber-grad);
  box-shadow: 0 0 10px rgba(232, 176, 106, 0.32);
}
input[type="checkbox"]:checked::before { left: 18px; }
input[type="checkbox"]:active::before { transform: scale(0.9); }


