.pp-brand .brand-mark { width: 28px; height: 28px; border-radius: 9px; }
.pp-brand .brand-mark .ui-ic svg { width: 15px; height: 15px; }
.pp-brandname {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--txt);
  white-space: nowrap;
