  border-radius: 50%;
  background: radial-gradient(circle, rgba(232,176,106,0.16) 0%, rgba(232,176,106,0.05) 42%, transparent 70%);
  filter: blur(6px);
  pointer-events: none;
  animation: aura-breathe 5s ease-in-out infinite;
