}
.dock .tab .ui-ic { margin: 0; flex: 0 0 auto; }
.dock .tab .ui-ic svg { width: 15px; height: 15px; }
.dock .tab:hover {
  background: rgba(255,255,255,0.08);
  color: var(--txt);
  transform: translateY(-1px);
}

