  padding: 12px 5px 9px;
  box-shadow: 0 0 16px rgba(232, 176, 106, 0.14);
}
.pet-thumb { width: 48px; height: 48px; image-rendering: pixelated; }
.pet-del {
  position: absolute; top: 5px; right: 7px;
  font-size: 10px; color: var(--sec);
  visibility: hidden; cursor: pointer; padding: 2px;
  z-index: 2;
}
.pet-item:hover .pet-del { visibility: visible; }
.pet-del:hover { color: var(--red); }

.pager-nav { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 12px; }
.pager-nav button {
