.pg-ind { display: flex; gap: 6px; align-items: center; font-size: 11px; color: var(--sec); min-width: 48px; justify-content: center; }
.pg-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.22); cursor: pointer; transition: background 0.15s ease; }
.pg-dot.sel { background: var(--amber); box-shadow: 0 0 7px rgba(232,176,106,0.6); }

.two-btns { display: flex; gap: 8px; margin-top: 13px; justify-content: flex-start; }
