/* ============================================================================
   5. REDUCED MOTION / PERFORMANCE MODE
   Continuous animations on transparent WebView2 windows keep the compositor
   awake. Disable them when the user opts in or the OS requests reduced motion.
============================================================================ */
body.reduce-motion #ball,
body.reduce-motion #pet.bob,
body.reduce-motion .bubble .brow.waiting .amsg,
body.reduce-motion .bubble .amsg.shimmer,
body.reduce-motion .bubble .sdot.plain.spin::after,
body.reduce-motion .bubble .sdot.claude.spin::after {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  #ball,
  #pet.bob,
  .bubble .brow.waiting .amsg,
  .bubble .amsg.shimmer,
  .bubble .sdot.plain.spin::after,
  .bubble .sdot.claude.spin::after {
    animation: none !important;
  }
  .page.sel { animation: none !important; }
  .modal, .modal-backdrop { animation: none !important; }
}

