.pop-agent[data-state="waiting"] .sess-dot { background: var(--orange); }
.pop-agent[data-state="done"] .sess-dot { background: var(--green); }
.pop-ameta { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.pop-ameta b { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pop-ameta .cap { font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pop-agent .sess-x { visibility: hidden; }
.pop-agent:hover .sess-x { visibility: visible; }
.pop-empty { padding: 4px 14px 10px; }
#pop-list { overflow-y: auto; max-height: 150px; flex: 0 1 auto; padding-bottom: 6px; }
.pop-row { display: flex; align-items: center; gap: 10px; padding: 9px 15px; font-size: 13px; cursor: pointer; transition: background 0.12s ease; }
.pop-row:hover { background: rgba(255,255,255,0.035); }
.pop-row .ui-ic { margin-right: 0; color: rgba(255,255,255,0.75); flex: 0 0 auto; }
.pop-row .ui-ic svg { width: 15px; height: 15px; }
.pop-label { flex: 1; }
.pop-row input[type="range"] { flex: 1; }
.pop-foot { display: flex; align-items: center; gap: 14px; padding: 11px 15px; }
.pop-foot .spacer { flex: 1; }
.pop-fbtn {
  background: none; border: 0; color: rgba(255,255,255,0.75);
  font-size: 12.5px; font-weight: 500; cursor: pointer;
  display: inline-flex; align-items: center; gap: 5px; padding: 0;
  transition: color 0.12s;
}
.pop-fbtn:hover { color: var(--amber); }
.pop-fbtn-quit { color: rgba(229, 122, 110, 0.75); }
.pop-fbtn-quit:hover { color: var(--red); }
.pop-fbtn .ui-ic { margin-right: 0; }
.pop-fbtn .ui-ic svg { width: 14px; height: 14px; }

/* ============================================================================
   5. REDUCED MOTION / PERFORMANCE MODE
   Continuous animations on transparent WebView2 windows keep the compositor
   awake. Disable them when the user opts in or the OS requests reduced motion.
============================================================================ */
body.reduce-motion #ball,
body.reduce-motion #pet.bob,
body.reduce-motion .bubble .brow.waiting .amsg,
body.reduce-motion .bubble .amsg.shimmer,
body.reduce-motion .bubble .sdot.plain.spin::after,
body.reduce-motion .bubble .sdot.claude.spin::after {
  animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
  #ball,
  #pet.bob,
  .bubble .brow.waiting .amsg,
  .bubble .amsg.shimmer,
  .bubble .sdot.plain.spin::after,
  .bubble .sdot.claude.spin::after {
    animation: none !important;
  }
  .page.sel { animation: none !important; }
  .modal, .modal-backdrop { animation: none !important; }
}

