 176	fn open_settings_impl(app: tauri::AppHandle) {
 177	    std::thread::spawn(move || {
 178	        dlog("open_settings: worker thread");
 179	        if let Some(w) = app.get_webview_window("settings") {
 180	            dlog("open_settings: existing window, showing");
 181	            let _ = w.show();
 182	            let _ = w.unminimize();
 183	            let _ = w.set_focus();
 184	            return;
 185	        }
 186	        match WebviewWindowBuilder::new(&app, "settings", WebviewUrl::App("settings.html".into()))
 187	            .title("DesktopPet")
 188	            .inner_size(1000.0, 680.0)
 189	            .min_inner_size(760.0, 560.0)
 190	            .resizable(true)
 191	            .build()
 192	        {
 193	            Ok(_) => dlog("open_settings: window created"),
 194	            Err(e) => dlog(&format!("open_settings: BUILD FAILED: {e}")),
 195	        }
 196	    });
 197	}
 405	/// Must be called from a worker thread, like open_settings_impl.
 406	fn spawn_floating_ball_impl(app: tauri::AppHandle) {
 407	    if app.get_webview_window(FLOATING_BALL_LABEL).is_some() {
 408	        return;
 409	    }
 410	    let (sw, sh) = primary_work_area(&app);
 411	    let (x, y) = read_ball_pos()
 412	        .filter(|&(x, y)| x >= 0.0 && x <= sw && y >= 0.0 && y <= sh)
 413	        .unwrap_or_else(|| (sw - BALL_W - 24.0, sh - BALL_H - 80.0));
 414	    let _ = WebviewWindowBuilder::new(
 415	        &app,
 416	        FLOATING_BALL_LABEL,
 417	        WebviewUrl::App("floating-ball.html".into()),
 418	    )
 419	    .title("DesktopPet")
 420	    .inner_size(BALL_W, BALL_H)
 421	    .position(x.max(0.0), y.max(0.0))
 422	    .transparent(true)
 423	    .decorations(false)
 424	    .always_on_top(true)
 425	    .skip_taskbar(true)
 426	    .resizable(false)
 427	    .shadow(false)
 428	    .focused(false)
 518	/// Show the popover (the macOS menu-bar popover equivalent) near the cursor.
 519	fn show_popover(app: &tauri::AppHandle) {
 520	    let win = match app.get_webview_window("popover") {
 521	        Some(w) => w,
 522	        None => {
 523	            match WebviewWindowBuilder::new(app, "popover", WebviewUrl::App("popover.html".into()))
 524	                .title("DesktopPet")
 525	                .inner_size(300.0, 430.0)
 526	                .decorations(false)
 527	                .transparent(true)
 528	                .always_on_top(true)
 529	                .skip_taskbar(true)
 530	                .resizable(false)
 531	                .focused(true)
 532	                .visible(false)
 533	                .build()
 534	            {
 535	                Ok(w) => {
 536	                    dlog("popover: window created");
 537	                    // Transient popover: losing focus hides it (Rust-side net,
 538	                    // independent of the webview's own blur listener).
 539	                    let wh = w.clone();
 540	                    w.on_window_event(move |ev| {
 100	  loadPopoverPet();
 101	  invoke<boolean>("get_desktop_pets_visible").then((visible) => { showPet.checked = visible; }).catch(() => {});
 102	});
 103	listen("pets-changed", () => {
 104	  syncSize();
 105	  loadPopoverPet();
 106	});
 107	
 108	// Hug the content height like the macOS popover (no dead space).
 109	let lastH = 0;
 110	function fitWindow() {
 111	  const card = document.querySelector(".pop-card") as HTMLElement;
 112	  if (!card) return;
 113	  const h = Math.min(560, Math.max(220, card.scrollHeight + 20));
 114	  if (Math.abs(h - lastH) < 2) return;
 115	  lastH = h;
 116	  getCurrentWindow().setSize(new LogicalSize(300, h)).catch(() => {});
 117	}
 118	fitWindow();
 119	
 120	applyStatic();

